// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! Integration-constraint VCs, one per connected port pair whose
//! destination in-port has an integration assume. Each states that the
//! sender's integration guarantee on the source out-port (or `true`, when
//! the sender declares none) implies the receiver's integration assume on
//! the destination in-port, over the value the connection carries. Static
//! (schedule- and property-independent) -- shared by the whole composition.
//! Each proof fn has an empty body: Verus discharges `requires ==> ensures`
//! via SMT; add proof hints in the body if a VC does not discharge.

#![allow(non_snake_case)]
#![allow(unused_variables)]
#![allow(unused_imports)]

use data::*;
use vstd::prelude::*;

use crate::contracts::*;

verus! {

/** VC[0]: Integration -- connection Isolette_System_Instance.temp_sensor.temp_sensor.current_temp -> Isolette_System_Instance.thermostat.thermostat.current_temp: sensor.current_temp's I-Guar `temp_range`
  * implies therm.current_temp's I-Assm `ASSM_CT_Range`, over
  * the value the connection carries. Discharges when the sender's
  * guarantee is at least as strong as the receiver's assume. */
pub proof fn vc_integration_sensor_current_temp_to_therm_current_temp(wire: Isolette_Data_Model::Temp)
  requires
    sensor::integration_spec_temp_range_guarantee(wire),
  ensures
    therm::integration_spec_ASSM_CT_Range_assume(wire),
{}

/** VC[1]: Integration -- connection Isolette_System_Instance.operator_interface.operator_interface.desired_temp -> Isolette_System_Instance.thermostat.thermostat.desired_temp: oi.desired_temp's I-Guar `LDT_LE_UDT`
  * implies therm.desired_temp's I-Assm `ASSM_LDT_LE_UDT`, over
  * the value the connection carries. Discharges when the sender's
  * guarantee is at least as strong as the receiver's assume. */
pub proof fn vc_integration_oi_desired_temp_to_therm_desired_temp(wire: Option<Isolette_Data_Model::Set_Points>)
  requires
    oi::integration_spec_LDT_LE_UDT_guarantee(wire),
  ensures
    therm::integration_spec_ASSM_LDT_LE_UDT_assume(wire),
{}

} // verus!
